import{_ as a,o as i,c as t,a5 as e}from"./chunks/framework.BjM_ivYE.js";const c=JSON.parse('{"title":"PTZ 카메라 API","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/ptz-camera-api.md","filePath":"ko/software/ptz-camera-api.md","lastUpdated":1788832277000}'),n={name:"ko/software/ptz-camera-api.md"};function l(p,s,h,r,o,d){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="ptz-카메라-api" tabindex="-1">PTZ 카메라 API <a class="header-anchor" href="#ptz-카메라-api" aria-label="Permalink to &quot;PTZ 카메라 API&quot;">​</a></h1><p>PTZ 카메라는 독립형 <a href="https://www.hanwhavision.com/ko/products/product-details/XNZ-L6320AG" target="_blank" rel="noreferrer">한화비전 XNZ-L6320AG</a>이며, 로봇 소프트웨어를 거치지 않고 <strong>카메라에 직접</strong> 제어합니다. 카메라는 로봇 내부 네트워크(기본 <code>192.168.0.100</code>)에 연결되어 있으며 세 가지 표준 인터페이스를 지원합니다.</p><ul><li><strong>RTSP</strong> — H.264 / H.265 라이브 영상</li><li><strong>SUNAPI</strong> — 팬 / 틸트 / 줌, 프리셋, 초점, 오디오를 제어하는 한화 HTTP CGI API</li><li><strong>ONVIF</strong> — 타사 VMS·도구 연동을 위한 Profile S / T</li></ul><p>카메라의 기구·광학 사양은 <a href="/RBQ/ko/manual/related-products/ptz-camera.html">PTZ 카메라</a>에서 확인하세요.</p><h2 id="control-paths" tabindex="-1">제어 경로 <a class="header-anchor" href="#control-paths" aria-label="Permalink to &quot;제어 경로 {#control-paths}&quot;">​</a></h2><p>PTZ 카메라를 코드로 제어하는 방법은 두 가지입니다.</p><table tabindex="0"><thead><tr><th></th><th>카메라에 직접 (이 페이지)</th><th>로봇 경유 (ROS2 / DDS)</th></tr></thead><tbody><tr><td>인터페이스</td><td>SUNAPI (HTTPS CGI) · RTSP · ONVIF Profile S / T</td><td><code>/rbq/cmd/ptz</code> · <code>/rbq/ptz</code> (<code>std_msgs/Float64MultiArray</code>)</td></tr><tr><td>접속 대상</td><td>카메라 <code>192.168.0.100</code></td><td>로봇의 DDS 도메인</td></tr><tr><td>팬 / 틸트 / 줌</td><td>절대·연속 이동, 프리셋, 초점</td><td>절대 팬 / 틸트 / 줌 setpoint — <strong>세 값이 함께 적용됨</strong></td></tr><tr><td>영상</td><td>카메라 RTSP, H.264 / H.265, 프로파일 선택</td><td>로봇 Streamer RTSP — <a href="/RBQ/ko/software/media.html">미디어</a> 참고</td></tr><tr><td>오디오</td><td>스피커·마이크 (SUNAPI 오디오, RTSP 백채널)</td><td>없음</td></tr><tr><td>타사 VMS 연동</td><td>ONVIF</td><td>없음</td></tr><tr><td>전제 조건</td><td>카메라 계정, 로봇 내부 네트워크 접근</td><td>로봇에서 <code>Ptz</code> 앱 실행 중</td></tr></tbody></table><p>로봇 SDK 코드의 한 흐름으로 카메라를 움직인다면 <a href="/RBQ/ko/software/sdk/ros/topics.html#vision-ptz-camera">ROS2 토픽</a>을 사용하세요. 프리셋·초점·오디오·ONVIF 등 카메라 고유 기능이 필요하다면 직접 제어를 사용합니다.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-caution-i" aria-hidden="true">!</span></div><div class="sb-content"><p class="custom-block-title">계정 정보</p><p>카메라는 HTTP <strong>Digest</strong> 인증(SUNAPI 기본)을 사용합니다. 예시의 <code>--anyauth</code>가 이를 자동으로 협상합니다 — <code>-u</code>만 쓰면 Basic만 전송되어 <strong>401</strong>로 거부됩니다. 로봇과 함께 제공되는 계정을 사용하고 <code>&lt;user&gt;</code> / <code>&lt;password&gt;</code>를 실제 계정으로 바꿔 주세요. 카메라는 신뢰할 수 있는 네트워크에서만 사용하세요.</p></div></div><h2 id="live-video-rtsp" tabindex="-1">라이브 영상 (RTSP) <a class="header-anchor" href="#live-video-rtsp" aria-label="Permalink to &quot;라이브 영상 (RTSP) {#live-video-rtsp}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ffplay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;rtsp://&lt;user&gt;:&lt;password&gt;@192.168.0.100:554/profile2/media.smp&quot;</span></span></code></pre></div><p>프로파일 번호로 스트림(해상도 / 코덱)을 선택합니다. 카메라의 프로파일 목록은 카메라 자체 웹 UI에서 확인할 수 있습니다.</p><h2 id="pan-tilt-zoom-sunapi" tabindex="-1">팬 / 틸트 / 줌 (SUNAPI) <a class="header-anchor" href="#pan-tilt-zoom-sunapi" aria-label="Permalink to &quot;팬 / 틸트 / 줌 (SUNAPI) {#pan-tilt-zoom-sunapi}&quot;">​</a></h2><p>SUNAPI는 HTTPS로 제공됩니다. 카메라는 자체 서명 인증서를 사용하므로 아래 예시에서는 <code>-k</code>(검증 생략)를 사용합니다. 자주 쓰는 호출:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 현재 줌 값 읽기</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --anyauth</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">passwor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;https://192.168.0.100/stw-cgi/ptzcontrol.cgi?msubmenu=query&amp;action=view&amp;Channel=0&amp;Query=Zoom&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 절대 줌 8배  (범위 1-32)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --anyauth</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">passwor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;https://192.168.0.100/stw-cgi/ptzcontrol.cgi?msubmenu=absolute&amp;action=control&amp;Zoom=8&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 연속 줌: 인 / 정지 / 아웃  -&gt;  1 / 0 / -1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --anyauth</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">passwor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;https://192.168.0.100/stw-cgi/ptzcontrol.cgi?msubmenu=continuous&amp;action=control&amp;Zoom=1&quot;</span></span></code></pre></div><p>팬·틸트·프리셋은 동일한 <code>ptzcontrol.cgi</code> 엔드포인트에서 <code>Pan</code> / <code>Tilt</code> 파라미터와 <code>msubmenu=preset</code>으로 제어합니다. 팬·틸트 범위, 프리셋, 초점, 오디오 입출력, 이벤트, 영상 설정 등 전체 명령은 XNZ-L6320AG의 <strong>한화 SUNAPI</strong> 레퍼런스를 참고하세요.</p><h2 id="speaker-microphone" tabindex="-1">스피커 &amp; 마이크 <a class="header-anchor" href="#speaker-microphone" aria-label="Permalink to &quot;스피커 &amp; 마이크 {#speaker-microphone}&quot;">​</a></h2><p>25 W 스피커와 마이크는 카메라 자체의 양방향 오디오이며, SUNAPI 오디오와 RTSP 백채널로 사용할 수 있습니다. 오디오 입출력은 한화 SUNAPI 레퍼런스를 참고하세요.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>위 인터페이스는 카메라에 직접 통신합니다. 로봇 소프트웨어도 합성 화면을 만들기 위해 카메라를 읽지만, 그 경로는 내부용입니다 — 연동에는 위의 표준 인터페이스나 ROS2 PTZ 토픽을 사용하세요.</p></div></div><h2 id="see-also" tabindex="-1">함께 보기 <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;함께 보기 {#see-also}&quot;">​</a></h2><ul><li><a href="/RBQ/ko/manual/related-products/ptz-camera.html">PTZ 카메라</a> — 기구·광학·열화상 사양</li><li><a href="/RBQ/ko/manual/gui/ptz.html">PTZ 카메라</a> — 앱에서 카메라 조작하기</li><li><a href="/RBQ/ko/software/sdk/ros/topics.html#vision-ptz-camera">토픽 레퍼런스 — 비전 — PTZ 카메라</a> — 로봇 경유 팬 / 틸트 / 줌 (ROS2)</li><li><a href="/RBQ/ko/software/media.html">미디어</a> — 로봇이 직접 발행하는 RTSP 스트림</li></ul>`,21)])])}const g=a(n,[["render",l]]);export{c as __pageData,g as default};
